//! Generated by `risc0_build::embed_methods`: `BLOCK_ELF`, `BLOCK_ID`,
//! `MIGRATE_ELF`, `MIGRATE_ID`. The IDs are consensus-critical (PRF-1, MIG-2,
//! PAR-5): a node only accepts receipts for these exact images, and the
//! network definition (`params.json`) pins them.
include!(concat!(env!("OUT_DIR"), "/methods.rs"));

/// The 32-byte form of an image ID: the eight words in little-endian byte
/// order (identical to `risc0_zkvm::sha::Digest::as_bytes`).
pub fn image_id_bytes(id: [u32; 8]) -> [u8; 32] {
    let mut out = [0u8; 32];
    for (i, w) in id.iter().enumerate() {
        out[i * 4..i * 4 + 4].copy_from_slice(&w.to_le_bytes());
    }
    out
}

pub fn block_image_id() -> [u8; 32] {
    image_id_bytes(BLOCK_ID)
}

pub fn migrate_image_id() -> [u8; 32] {
    image_id_bytes(MIGRATE_ID)
}
